            add_sssaaaaaa(P3, P2, P1, P3, P2, P1, UWORD(0), t1, t0);
            umul_ppmm(t1, t0, A1, B0);
            add_sssaaaaaa(P3, P2, P1, P3, P2, P1, UWORD(0), t1, t0);
