            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            sub_dddmmmsss(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), UWORD(0), (ma & B0));
            sub_dddmmmsss(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, UWORD(0), UWORD(0), (ma & B1));
            sub_dddmmmsss(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), UWORD(0), (mb & A0));
            sub_dddmmmsss(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, UWORD(0), UWORD(0), (mb & A1));

            a += 3;
            b -= 3;
