static void _flint_mpn_poly_sqrmid_3x3_7_signed(nn_ptr res, nn_srcptr f, slong flen, slong nlo, slong nhi)
{
    slong i, start, stop;
    nn_srcptr a, b, aend;
    ulong A0, A1, A2, B0, B1, B2;
    ulong p0, p1;
    ulong c0_0, c0_1, c0_2;
    ulong c1_0, c1_1, c1_2;
    ulong c2_0, c2_1, c2_2;
    ulong c3_0, c3_1, c3_2;
    ulong c4_0, c4_1, c4_2;
    ulong ma;
    ulong mb;
    ulong sx;
    ulong r0, r1, r2, r3, r4, r5, r6;

    for (i = nlo; i < nhi; i++)
    {
        /* cross terms f_j f_{i-j} with j < i - j, counted twice */
        start = FLINT_MAX(0, i - flen + 1);
        stop = FLINT_MIN(flen - 1, (i + 1) / 2 - 1);

        c0_0 = c0_1 = c0_2 = 0;
        c1_0 = c1_1 = c1_2 = 0;
        c2_0 = c2_1 = c2_2 = 0;
        c3_0 = c3_1 = c3_2 = 0;
        c4_0 = c4_1 = c4_2 = 0;

        a = f + start * 3;
        aend = f + (stop + 1) * 3;
        b = f + (i - start) * 3;

        for ( ; a < aend; )
        {
            A0 = a[0];
            A1 = a[1];
            A2 = a[2];
            B0 = b[0];
            B1 = b[1];
            B2 = b[2];
            ma = FLINT_SIGN_EXT(A2);
            mb = FLINT_SIGN_EXT(B2);

            umul_ppmm(p1, p0, A0, B0);
            add_sssaaaaaa(c0_2, c0_1, c0_0, c0_2, c0_1, c0_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A0, B1);
            add_sssaaaaaa(c1_2, c1_1, c1_0, c1_2, c1_1, c1_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A0, B2);
            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A1, B2);
            add_sssaaaaaa(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), p1, p0);
            smul_ppmm(p1, p0, A2, B2);
            sx = FLINT_SIGN_EXT(p1);
            add_sssaaaaaa(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, sx, p1, p0);
            umul_ppmm(p1, p0, A1, B0);
            add_sssaaaaaa(c1_2, c1_1, c1_0, c1_2, c1_1, c1_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A1, B1);
            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A2, B1);
            add_sssaaaaaa(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A2, B0);
            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            sub_dddmmmsss(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), UWORD(0), (ma & B0));
            sub_dddmmmsss(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, UWORD(0), UWORD(0), (ma & B1));
            sub_dddmmmsss(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), UWORD(0), (mb & A0));
            sub_dddmmmsss(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, UWORD(0), UWORD(0), (mb & A1));

            a += 3;
            b -= 3;
        }

        r0 = c0_0;
        r1 = c0_1;
        r2 = c0_2;
        r3 = UWORD(0);
        r4 = UWORD(0);
        r5 = UWORD(0);
        r6 = UWORD(0);
        add_ssssssaaaaaaaaaaaa(r6, r5, r4, r3, r2, r1, r6, r5, r4, r3, r2, r1, UWORD(0), UWORD(0), UWORD(0), c1_2, c1_1, c1_0);
        add_sssssaaaaaaaaaa(r6, r5, r4, r3, r2, r6, r5, r4, r3, r2, UWORD(0), UWORD(0), c2_2, c2_1, c2_0);
        sx = FLINT_SIGN_EXT(c3_2);
        add_ssssaaaaaaaa(r6, r5, r4, r3, r6, r5, r4, r3, sx, c3_2, c3_1, c3_0);
        add_sssaaaaaa(r6, r5, r4, r6, r5, r4, c4_2, c4_1, c4_0);

        /* double */
        add_sssssssaaaaaaaaaaaaaa(r6, r5, r4, r3, r2, r1, r0, r6, r5, r4, r3, r2, r1, r0, r6, r5, r4, r3, r2, r1, r0);

        /* square term */
        if (i % 2 == 0)
        {
            a = f + (i / 2) * 3;
            A0 = a[0];
            A1 = a[1];
            A2 = a[2];
            B0 = A0;
            B1 = A1;
            B2 = A2;
            ma = FLINT_SIGN_EXT(A2);
            mb = FLINT_SIGN_EXT(B2);
            c0_0 = c0_1 = c0_2 = 0;
            c1_0 = c1_1 = c1_2 = 0;
            c2_0 = c2_1 = c2_2 = 0;
            c3_0 = c3_1 = c3_2 = 0;
            c4_0 = c4_1 = c4_2 = 0;
            umul_ppmm(p1, p0, A0, B0);
            add_sssaaaaaa(c0_2, c0_1, c0_0, c0_2, c0_1, c0_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A0, B1);
            add_sssaaaaaa(c1_2, c1_1, c1_0, c1_2, c1_1, c1_0, UWORD(0), p1, p0);
            add_sssaaaaaa(c1_2, c1_1, c1_0, c1_2, c1_1, c1_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A0, B2);
            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            umul_ppmm(p1, p0, A1, B2);
            add_sssaaaaaa(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), p1, p0);
            add_sssaaaaaa(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), p1, p0);
            smul_ppmm(p1, p0, A2, B2);
            sx = FLINT_SIGN_EXT(p1);
            add_sssaaaaaa(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, sx, p1, p0);
            umul_ppmm(p1, p0, A1, B1);
            add_sssaaaaaa(c2_2, c2_1, c2_0, c2_2, c2_1, c2_0, UWORD(0), p1, p0);
            sub_dddmmmsss(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), UWORD(0), (ma & B0));
            sub_dddmmmsss(c3_2, c3_1, c3_0, c3_2, c3_1, c3_0, UWORD(0), UWORD(0), (ma & B0));
            sub_dddmmmsss(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, UWORD(0), UWORD(0), (ma & B1));
            sub_dddmmmsss(c4_2, c4_1, c4_0, c4_2, c4_1, c4_0, UWORD(0), UWORD(0), (ma & B1));
            add_sssssssaaaaaaaaaaaaaa(r6, r5, r4, r3, r2, r1, r0, r6, r5, r4, r3, r2, r1, r0, UWORD(0), UWORD(0), UWORD(0), UWORD(0), c0_2, c0_1, c0_0);
            add_ssssssaaaaaaaaaaaa(r6, r5, r4, r3, r2, r1, r6, r5, r4, r3, r2, r1, UWORD(0), UWORD(0), UWORD(0), c1_2, c1_1, c1_0);
            add_sssssaaaaaaaaaa(r6, r5, r4, r3, r2, r6, r5, r4, r3, r2, UWORD(0), UWORD(0), c2_2, c2_1, c2_0);
            sx = FLINT_SIGN_EXT(c3_2);
            add_ssssaaaaaaaa(r6, r5, r4, r3, r6, r5, r4, r3, sx, c3_2, c3_1, c3_0);
            add_sssaaaaaa(r6, r5, r4, r6, r5, r4, c4_2, c4_1, c4_0);
        }

        res[0] = r0;
        res[1] = r1;
        res[2] = r2;
        res[3] = r3;
        res[4] = r4;
        res[5] = r5;
        res[6] = r6;
        res += 7;
    }
}

static void _flint_mpn_poly_mulmid_4x1_4_short(nn_ptr res, nn_srcptr f, slong flen, nn_srcptr g, slong glen, slong nlo, slong nhi)
{
    slong i, top1, top2;
    nn_srcptr a, b, aend;
    ulong r0, r1, r2, r3;
    ulong t[5];

    for (i = nlo; i < nhi; i++)
    {
        top1 = FLINT_MIN(flen - 1, i);
        top2 = FLINT_MIN(glen - 1, i);
        a = f + (i - top2) * 4;
        aend = a + (top1 + top2 - i + 1) * 4;
        b = g + top2 * 1;

        r0 = r1 = r2 = r3 = 0;

        for ( ; a != aend; )
        {
            flint_mpn_mul(t, a, 4, b, 1);
            add_ssssaaaaaaaa(r3, r2, r1, r0, r3, r2, r1, r0, t[3], t[2], t[1], t[0]);

            a += 4;
            b -= 1;
        }

        res[0] = r0;
        res[1] = r1;
        res[2] = r2;
        res[3] = r3;
        res += 4;
    }
}

